    readFileSync(path.join(dir, 'calls.jsonl'), 'utf8').trimEnd().split('\n').map(line => JSON.parse(line) as unknown);

  beforeEach(() => {
    dir = mkdtempSync(path.join(tmpdir(), 'resolve-confirm-'));
